entries=[]
for family,(prefix,chassis,silhouette,power,names,inputs,triggers,results,costs,counters,visuals) in F.items():
    mounts=['core','tool','support']
    for i,name in enumerate(names):
        bid=f'{prefix}_{i+1:02d}'
        p=[]
        for stage,label in enumerate(['核心','升级一','升级二','升级三']):
            pid=f'{bid}.p{stage}'
            p.append({'part_id':pid,'name':f'{name}·{label}件','mount':mounts[stage%3],'joint_and_function':(['提供基础作业与底盘承载',inputs[i],results[i],f'让{chassis}在终局形成独立的超大型工作姿态'][stage]),'power_from':power,'removal_consequence':(['车辆回到无构筑基础作业',costs[i],counters[i],f'失去{name}终局的核心形态与收尾动作'][stage])})
        entries.append({'build_id':bid,'name':name,'family':family,'status':'proposal','prototype_priority':1 if i<2 else 2,'operation':{'input':inputs[i],'trigger':triggers[i],'result':results[i]},'cost':costs[i],'parts':p,'growth':[{'stage':0,'active_parts':[p[0]['part_id']],'change':f'核心形态：{silhouette}，只保留基础工程动词。'},{'stage':1,'active_parts':[p[0]['part_id'],p[1]['part_id']],'change':f'升级一装入{p[1]["name"]}，改变{inputs[i]}并增加新的操作窗口。'},{'stage':2,'active_parts':[p[0]['part_id'],p[1]['part_id'],p[2]['part_id']],'change':f'升级二接入动力链，{results[i]}获得新的空间/路线用法。'},{'stage':3,'active_parts':[x['part_id'] for x in p],'change':f'升级三完成终局重构：{visuals[i]}；不是整体缩放。'}],'counterplay':counters[i],'failure_test':f'让普通敌人、对应精英和一处工程目标同场：验证{name}的触发、代价、反制、拆件缺失和读档恢复。','visual_signature':visuals[i],'feedback':{'vfx':f'{name}的动作只由权威事件驱动，阶段0/1/2/3分别显示部件变化。','audio':f'{name}使用核心机械声、升级一接合声、升级二动力声、升级三终局声四层反馈。','ui':f'卡面显示输入“{inputs[i]}”、触发“{triggers[i]}”、结果“{results[i]}”和代价“{costs[i]}”。'},'save_identity':{'namespace':bid,'state_keys':['build_id','stage','part_ids','operation_state','world_checkpoint']},'evidence':{'behavior':'not_run','assembly':'not_run','gpu':'not_run','audio':'not_run','save':'not_run'}})
payload={'schema_version':3,'title':'100种幻想机械构筑：四段部件成长提案','status':'proposal','scope':'每条构筑由核心件与升级1/2/3四段部件链组成；全部仍待Godot行为、Blender拆件和真实镜头验收。','families':{k:{'prefix':v[0],'count':10,'chassis':v[1],'silhouette':v[2],'power_chain':v[3]} for k,v in F.items()},'shared_contract':{'growth':'stage 0核心、stage 1升级一、stage 2升级二、stage 3升级三；升级必须增加可见部件、动作或工作包络。','assembly':'每个 part_id 独立网格、命名枢轴、连接面、碰撞代理和移除后果；没有幽灵效果。','save':'保存 build_id、stage、part_ids、operation_state、world_checkpoint。','quality':'72px剪影盲认、禁用VFX、真实输入、GPU截图、断档恢复后才能晋级。'},'builds':entries}
